// Test script to verify the healthz endpoint logic
// This simulates the expected behavior without needing a real database

const express = require('express');
const app = express();

// Mock database module for testing
const mockDb = {
  checkDatabaseConnection: async () => {
    // In a real scenario, this would connect to the database
    // For testing purposes, we'll simulate a successful connection
    return true;
  }
};

app.get('/healthz', async (req, res) => {
  try {
    const dbOk = await mockDb.checkDatabaseConnection();

    if (dbOk) {
      res.status(200).json({ db: 'ok' });
    } else {
      res.status(503).json({ db: 'unhealthy' });
    }
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ db: 'unhealthy' });
  }
});

// Test the endpoint
const http = require('http');
const server = app.listen(3001, async () => {
  console.log('Test server running on port 3001');

  // Test the /healthz endpoint
  http.get('http://localhost:3001/healthz', (resp) => {
    let data = '';

    resp.on('data', (chunk) => {
      data += chunk;
    });

    resp.on('end', () => {
      console.log('Response status:', resp.statusCode);
      console.log('Response data:', data);
      console.log('Test completed!');
      server.close();
    });
  }).on('error', (err) => {
    console.error('Test error:', err);
    server.close();
  });
});

