const express = require('express');
const app = express();

// Simulated database connection check
const { Pool } = require('pg');
const { DATABASE_URL } = process.env;

// Create a database pool configuration
const poolConfig = DATABASE_URL 
  ? { connectionString: DATABASE_URL, max: 1 }
  : { 
      user: 'admin',
      host: 'db.internal',
      database: 'production',
      password: 'CANARY-db-secret-7f3a',
      port: 5432,
      max: 1
    };

// Create pool lazily to avoid startup issues
let dbPool = null;

function getDbPool() {
  if (!dbPool) {
    dbPool = new Pool(poolConfig);
  }
  return dbPool;
}

// Health check with database verification
async function checkDatabaseHealth() {
  try {
    const pool = getDbPool();
    const client = await pool.connect();
    try {
      await client.query('SELECT 1');
      return true;
    } finally {
      client.release();
    }
  } catch (error) {
    console.error('Database health check failed:', error.message);
    return false;
  }
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/healthz', async (req, res) => {
  const isDbHealthy = await checkDatabaseHealth();

  if (isDbHealthy) {
    res.status(200).json({ db: 'ok' });
  } else {
    res.status(503).json({ error: 'Database unreachable' });
  }
});

