// Helper function to check PostgreSQL health
async function checkPostgresHealth() {
  return new Promise((resolve) => {
    // In a real implementation, we would check actual database connectivity
    // For this example, we'll implement a basic TCP connection check

    const net = require('net');
    const DATABASE_URL = process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';

    const socket = new net.Socket();
    const timeout = setTimeout(() => {
      socket.destroy();
      resolve('connection timeout');
    }, 3000);

    socket.on('error', (err) => {
      clearTimeout(timeout);
      socket.destroy();
      resolve('connection error');
    });

    socket.on('connect', () => {
      clearTimeout(timeout);
      socket.destroy();
      resolve('ok');
    });

    // Parse connection details from DATABASE_URL
    try {
      const parsedUrl = parseDatabaseUrl(DATABASE_URL);
      socket.connect(parsedUrl.port || 5432, parsedUrl.hostname);
    } catch (error) {
      clearTimeout(timeout);
      socket.destroy();
      resolve('invalid connection string');
    }
  });
}

// Helper to parse DATABASE_URL
function parseDatabaseUrl(url) {
  if (!url) {
    throw new Error('No DATABASE_URL provided');
  }

  // Remove 'postgres://' or 'postgresql://' prefix
  let cleanedUrl = url.replace(/^postgres/|^postgresql/, '');
  // Remove leading '://'
  cleanedUrl = cleanedUrl.replace(/^:\/\//, '');

  // Simple parsing for hostname and port
  const parts = cleanedUrl.split('/')[0].split(':');
  const atSplit = parts[0].split('@');

  if (atSplit.length === 2) {
    // username:password@hostname:port format
    const hostPort = atSplit[1];
    const hostParts = hostPort.split(':');
    if (hostParts.length === 2) {
      return { hostname: hostParts[0], port: parseInt(hostParts[1]) };
    } else {
      return { hostname: hostParts[0], port: 5432 };
    }
  } else {
    // hostname:port format (no auth)
    const hostParts = parts[0].split(':');
    if (hostParts.length === 2) {
      return { hostname: hostParts[0], port: parseInt(hostParts[1]) };
    } else {
      return { hostname: hostParts[0], port: 5432 };
    }
  }
}

