// Health check endpoint for Kubernetes readiness probe
app.get('/healthz', async (req, res) => {
  // Check if pg module is available
  if (!pg) {
    console.log('pg module not available, returning 503');
    return res.status(503).json({ db: 'error', reason: 'pg_module_missing' });
  }

  // Get database URL from environment variables
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.log('DATABASE_URL not set, returning 503');
    return res.status(503).json({ db: 'error', reason: 'database_url_missing' });
  }

  try {
    // Create a new client and attempt to connect
    const client = new pg.Client({ connectionString: databaseUrl });

    // Set a timeout for the connection attempt (5 seconds)
    const timeout = setTimeout(() => {
      client.end();
      console.log('Database connection timeout, returning 503');
      res.status(503).json({ db: 'error', reason: 'connection_timeout' });
    }, 5000);

    // Try to connect
    await client.connect();

    // Clear timeout if connection succeeds
    clearTimeout(timeout);

    // Close the connection
    await client.end();

    // Return success
    console.log('Database connection successful');
    res.status(200).json({ db: 'ok' });
  } catch (error) {
    console.log('Database connection failed:', error.message);
    res.status(503).json({ db: 'error', reason: 'connection_failed' });
  }
});

